"""Offline selector: no server, fetch, external scripts, or game-project changes."""
import html
import json
from inventory import ROOT


def build_gallery(manifest):
    esc=html.escape
    cards=''.join(f'''<article data-asset="{a['id']}"><a class="preview-link" href="previews/combinations/{a['id']}/white__black.png"><img loading="lazy" width="480" height="360" src="previews/combinations/{a['id']}/white__black.png" alt="{esc(a['id'].replace('_',' ').title())}"></a><h2>{esc(a['id'].replace('_',' ').title())}</h2><p><a href="previews/matrices/{a['id']}.png">121-pair matrix</a> · <a href="previews/ships/{a['id']}.png">Presets</a> · <a href="previews/inspection/{a['id']}.png">Inspection</a> · <a href="previews/blender/{a['id']}.blend">Blender</a></p></article>''' for a in manifest['assets'])
    options=lambda family:''.join(f'<option value="{key}">{esc(v["label"])}</option>' for key,v in manifest[family].items())
    preset_options=''.join(f'<option value="{key}">{esc(v["label"])}</option>' for key,v in manifest['palettes'].items())
    data=json.dumps({key:manifest[key] for key in ['hull_colors','detail_colors','palettes']}).replace('</','<\\/')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fleet paint | Choose your colors</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101923;color:#ecf1f4;font:16px/1.55 system-ui,sans-serif}main{max-width:1480px;margin:auto;padding:36px 24px}h1{font-size:42px;letter-spacing:-1px;margin:0}h2{font-size:19px;margin:14px 16px 4px}p{color:#a8b9c9}a{color:#acd4f3}a:hover{color:white}.eyebrow{letter-spacing:2px;font-size:12px;text-transform:uppercase;color:#a8b9c9}.toolbar{position:sticky;top:0;z-index:5;margin:24px 0;background:#172431f5;border:1px solid #3c5061;border-radius:6px;padding:18px;box-shadow:0 8px 24px #0004}.controls{display:flex;flex-wrap:wrap;align-items:end;gap:18px}.field{display:grid;gap:6px}.field label{font-size:13px;color:#bdd0df}.picker{display:flex;gap:6px;align-items:center}button,select{font:inherit;min-height:42px;background:#263a4b;border:1px solid #587084;border-radius:4px;color:#fff;padding:7px 12px;cursor:pointer}button:hover,select:hover{background:#344e62}button:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid #a9d5ff;outline-offset:3px}.swatch{width:28px;height:28px;border:1px solid #8ca0ae;border-radius:50%;display:inline-block;flex:none}select{max-width:245px}.status{margin:12px 0 0;font-size:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}article{background:#1b2836;border-radius:6px;overflow:hidden}article img{width:100%;height:auto;display:block}article p{margin:5px 16px 17px;font-size:13px}.links{display:flex;gap:14px;flex-wrap:wrap;font-size:14px}details{margin:22px 0;background:#1b2836;padding:14px 18px;border-radius:4px}summary{cursor:pointer}code{font-size:13px;overflow-wrap:anywhere}#command{display:block;user-select:all;margin-top:10px;color:#c4dced}.source{font-size:13px;display:flex;gap:8px;align-items:center}.source input{width:18px;height:18px}.small{font-size:13px}@media(max-width:600px){main{padding:24px 12px}h1{font-size:32px}.toolbar{position:relative}.controls{gap:12px}.field{width:100%}.picker select{flex:1}.grid{grid-template-columns:1fr}}</style>
<main><div class="eyebrow">Fleet paint library / v2</div><h1>Choose your fleet colors</h1><p>11 hull colors. 11 detail colors. All 121 pairings, matched across 19 ships and support assets.</p>
<nav class="links"><a href="README.md">Quick start</a><a href="PIPELINE.md">Add ships & colors</a><a href="integration/README.md">Pre-match integration</a><a href="validation.json">Validation</a><a href="previews/fleets/original.png">Standardized original fleet</a><a href="previews/fleets/white_black.png">White / black fleet</a></nav>
<section class="toolbar" aria-label="Fleet color selector"><div class="controls"><div class="field"><label for="hull">Hull paint</label><div class="picker"><span id="hull-swatch" class="swatch"></span><button id="hull-prev" aria-label="Previous hull color">‹</button><select id="hull">'''+options('hull_colors')+'''</select><button id="hull-next" aria-label="Next hull color">›</button></div></div><div class="field"><label for="detail">Details / stripes</label><div class="picker"><span id="detail-swatch" class="swatch"></span><button id="detail-prev" aria-label="Previous detail color">‹</button><select id="detail">'''+options('detail_colors')+'''</select><button id="detail-next" aria-label="Next detail color">›</button></div></div><div class="field"><label for="preset">Preset</label><select id="preset"><option value="">Custom pairing</option>'''+preset_options+'''</select></div><label class="source"><input id="source" type="checkbox">Historical source paint</label></div><p id="status" class="status" aria-live="polite"></p></section>
<div class="grid">'''+cards+'''</div><details><summary>Export the selected pair</summary><p class="small">The layered library covers every pairing. Bake a selected pair once, then reuse the cached textures before a match. Ready-made PNGs are included for all presets. This catalog previews actual Blender renders.</p><code id="command"></code><p class="small"><a href="exports/white__black/materials.json">Ready-to-use white / black export manifest</a> · The Python exporter also supports <code>--all</code> for every full-resolution pairing.</p></details><p class="small">Original source files remain unchanged. The “original” preset uses standardized ivory and oxide-red paint; “historical source paint” shows the archived finish. Preview textures are capped at 2048 px. Exported textures retain source resolution. Individually framed models are not to scale. Carrier and carrier modules are excluded.</p></main>
<script id="paint-data" type="application/json">'''+data+'''</script><script>
const data=JSON.parse(document.getElementById('paint-data').textContent);
const hull=document.getElementById('hull'),detail=document.getElementById('detail'),preset=document.getElementById('preset'),source=document.getElementById('source');
function update(){
 const h=hull.value,d=detail.value; document.getElementById('hull-swatch').style.background=data.hull_colors[h].srgb;document.getElementById('detail-swatch').style.background=data.detail_colors[d].srgb;
 const match=Object.entries(data.palettes).find(([key,p])=>p.hull===h&&p.detail===d);preset.value=source.checked?'':(match?match[0]:'');
 document.querySelectorAll('[data-asset]').forEach(card=>{const id=card.dataset.asset,path=source.checked?'previews/raw/'+id+'/source_overview.png':'previews/combinations/'+id+'/'+h+'__'+d+'.png';card.querySelector('img').src=path;card.querySelector('.preview-link').href=path;});
 const count=Object.keys(data.hull_colors).length*Object.keys(data.detail_colors).length;
 document.getElementById('status').textContent=source.checked?'Historical source paint — preserved for comparison':data.hull_colors[h].label+' hull / '+data.detail_colors[d].label+' details · '+count+' available pairings';
 document.getElementById('command').textContent='python artwork/player_colors/scripts/bake_pair.py --hull '+h+' --detail '+d;
 history.replaceState(null,'','#'+h+'__'+d+(source.checked?'__source':''));
}
function cycle(select,step){select.selectedIndex=(select.selectedIndex+step+select.options.length)%select.options.length;source.checked=false;update();}
for(const [name,select] of [['hull',hull],['detail',detail]]){document.getElementById(name+'-prev').onclick=()=>cycle(select,-1);document.getElementById(name+'-next').onclick=()=>cycle(select,1);select.onchange=()=>{source.checked=false;update();};}
preset.onchange=()=>{const p=data.palettes[preset.value];if(p){hull.value=p.hull;detail.value=p.detail;source.checked=false;update();}};
source.onchange=update;
const initial=location.hash.slice(1).split('__');hull.value=data.hull_colors[initial[0]]?initial[0]:'white';detail.value=data.detail_colors[initial[1]]?initial[1]:'black';source.checked=initial[2]==='source';update();
</script></html>'''
    page=page.replace('11 hull colors. 11 detail colors. All 121 pairings, matched across 19 ships and support assets.',
        str(len(manifest['hull_colors']))+' hull colors. '+str(len(manifest['detail_colors']))+' detail colors. All '+
        str(len(manifest['mix_and_match']['combinations']))+' pairings, matched across '+str(len(manifest['assets']))+' ships and support assets.')
    (ROOT/'index.html').write_text(page,encoding='utf-8')
